const localDate=()=>dateParts(new Date())
const localDateFromISO=(value:string)=>{const d=new Date(value);return Number.isNaN(d.getTime())?String(value||'').slice(0,10):dateParts(d)}
const abbr=(t:any)=>t?.abbrev||t?.triCode||'???'; const name=(n:any)=>typeof n==='string'?n:n?.default||''; const teamFullName=(t:any)=>{const place=name(t?.placeName),common=name(t?.commonName),direct=name(t?.name);return [place,common].filter(Boolean).join(' ')||direct||abbr(t)}
const ordinal=(n:number)=>n===1?'1st':n===2?'2nd':n===3?'3rd':`${n}th`; const clockToSeconds=(c='00:00')=>{const [m,s]=c.split(':').map(Number);return(m||0)*60+(s||0)}
function parseLandingGoals(landing:any,game:Game,pbp?:any):FeedEvent[]{const out:FeedEvent[]=[];let sequence=0;const goalTimes=new Map<string,number>();for(const p of(pbp?.plays||[])){if(String(p?.typeDescKey||'')!=='goal')continue;const pn=Number(p?.periodDescriptor?.number)||0,clock=String(p?.timeInPeriod||'');goalTimes.set(`${pn}|${clock}`,playCompletionMoment(p,game).sort)}for(const pb of(landing?.summary?.scoring||landing?.scoring||[])){const pn=Number(pb?.periodDescriptor?.number)||0;for(const goal of(pb?.goals||[])){sequence++;const team=name(goal.teamAbbrev)||goal.teamAbbrev||'NHL';const opponent=team===abbr(game.homeTeam)?abbr(game.awayTeam):abbr(game.homeTeam);const scorer=name(goal.name)||[name(goal.firstName),name(goal.lastName)].filter(Boolean).join(' ')||'Unknown scorer';const total=goal.goalsToDate;const assists=(goal.assists||[]).map((a:any)=>{const nm=name(a.name)||[name(a.firstName),name(a.lastName)].filter(Boolean).join(' ');return nm?`${nm}${a.assistsToDate!=null?` (${a.assistsToDate})`:''}`:''}).filter(Boolean).join(', ');let badge=String(goal.strength||'').toUpperCase();if(!['PPG','SHG'].includes(badge))badge='';if(String(goal.goalModifier||'').toLowerCase().includes('empty'))badge=badge?`${badge} · EN`:'EN';out.push({id:`${game.id}-goal-${sequence}`,gameId:game.id,team,opponent,type:'GOAL',title:`${scorer}${total!=null?`: ${total}`:''}${badge?` · ${badge}`:''}`,detail:`Scorer: ${scorer} · Assists: ${assists||'Unassisted'}`,meta:`${abbr(game.awayTeam)} ${goal.awayScore??'-'} – ${abbr(game.homeTeam)} ${goal.homeScore??'-'} · ${pn?ordinal(pn):''} · ${goal.timeInPeriod||''}`,sort:goalTimes.get(`${pn}|${goal.timeInPeriod||''}`)||playCompletionMoment({periodDescriptor:{number:pn},timeInPeriod:goal.timeInPeriod},game).sort,sequence})}}return out}
const hash=(s:string)=>{let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16).toUpperCase().padStart(8,'0')}
const normalizeBet=(date:string,legs:Leg[],book:string,units:number,unitSize:number,payout?:number,odds?:number):Bet=>{const clean=legs.map(l=>({player:l.player.trim(),qty:Number(l.qty),stat:STATS[l.stat.toLowerCase()]||l.stat.trim(),playerId:l.playerId,team:l.team,opponent:l.opponent,position:l.position,gameId:l.gameId,kind:l.kind}));const signature=`${date}|${clean.map(l=>`${l.player.toLowerCase()}:${l.qty}:${l.stat.toLowerCase()}`).join('+')}|${book.toLowerCase()}|${units}|${payout??''}|${odds??''}`;return{id:`${date.replaceAll('-','')}-${hash(signature)}`,date,legs:clean,book:book.trim(),units:Number(units),unitSize:Number(unitSize),payout:payout==null?undefined:Number(payout),odds:odds==null?undefined:Number(odds),createdAt:new Date().toISOString(),groupKey:'UNASSIGNED',status:'PENDING'}}
