function playEventSound(type:FeedType,volume:number){
 try{const Ctx=(window.AudioContext||(window as any).webkitAudioContext);if(!Ctx)return;const ctx=new Ctx();const gain=ctx.createGain();gain.connect(ctx.destination);gain.gain.setValueAtTime(Math.max(0,Math.min(1,volume)),ctx.currentTime);const map:Record<FeedType,number[]>={'GAME START':[1050,1320,1050],GOAL:[740,990],'POWER PLAY':[440,660],'EMPTY NET':[520,390],INTERMISSION:[330,440],FINAL:[880,660],'BET HIT':[880,1175],'STAT CORRECTION':[320,240,320],'NIGHT VERIFIED':[660,880]};const notes=map[type]||[660];notes.forEach((freq,i)=>{const o=ctx.createOscillator();const g=ctx.createGain();o.type=type==='STAT CORRECTION'?'square':'sine';o.frequency.value=freq;o.connect(g);g.connect(gain);const st=ctx.currentTime+i*.12;g.gain.setValueAtTime(.0001,st);g.gain.exponentialRampToValueAtTime(.22,st+.015);g.gain.exponentialRampToValueAtTime(.0001,st+.105);o.start(st);o.stop(st+.12)});setTimeout(()=>ctx.close(),800)}catch{}
}

