  <style>{`.onIceNow{margin:10px 0 12px;padding:10px 12px;border:1px solid rgba(255,255,255,.12);border-radius:9px;background:rgba(8,14,20,.72)}.onIceHead{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}.onIceHead small{opacity:.58;font-size:9px;letter-spacing:.08em}.onIceGrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.onIceTeam>b{display:block;margin-bottom:5px;font-size:12px}.onIceTeam>div{display:flex;flex-wrap:wrap;gap:5px}.onIceTeam span{padding:4px 7px;border:1px solid rgba(255,255,255,.12);border-radius:999px;font-size:11px}.onIceTeam em{opacity:.55;font-size:11px;font-style:normal}.eventContent footer time{white-space:nowrap}.eventTrackerTitle{position:relative}.eventFilterControls{display:flex;align-items:center;gap:10px}.mixerButton{width:32px;height:32px;padding:6px;border:1px solid rgba(255,255,255,.18);border-radius:7px;background:rgba(255,255,255,.04);color:inherit;display:grid;place-items:center;cursor:pointer}.mixerButton svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round}.mixerButton.active{border-color:#f5a623;background:rgba(245,166,35,.12)}.eventFilterPanel{display:flex;flex-wrap:wrap;gap:8px 14px;align-items:center;padding:9px 12px;margin:0 0 8px;border:1px solid rgba(255,255,255,.12);border-radius:8px;background:rgba(8,14,20,.96)}.eventFilterPanel label{display:flex;align-items:center;gap:6px;font-size:12px;white-space:nowrap}.eventFilterPanel button{margin-left:auto;font-size:10px;padding:5px 8px}.eventSelectable{cursor:pointer}.eventSelectable:focus-visible{outline:2px solid currentColor;outline-offset:-2px}.liveClock.emptyNet{color:#ff9f2f!important;border-color:#ff9f2f!important}.liveClock.emptyNet .clockMotion{background:#ff9f2f!important}.gameVerifyBar{display:flex;align-items:center;gap:10px;padding:8px 12px;border-top:1px solid rgba(255,255,255,.06);border-bottom:1px solid rgba(255,255,255,.06)}.gameVerifyBar small{font-size:10px;opacity:.7}.gameVerifyBar .verifyButton{padding:7px 10px;font-size:10px}.liveBetAccordion>summary{grid-template-columns:minmax(250px,1.15fr) minmax(320px,1.4fr) minmax(130px,.55fr) auto auto!important}.rowVerifyButton{margin-left:10px;padding:6px 10px;border:1px solid #27d995;border-radius:7px;background:rgba(39,217,149,.10);color:#62efb8;font-size:9px;font-weight:900;letter-spacing:.04em;white-space:nowrap;cursor:pointer}.rowVerifyButton:hover{background:rgba(39,217,149,.18)}.rowVerifyButton:disabled{opacity:.6;cursor:wait}.rowVerifyButton.verified{border-color:#27d995;color:#62efb8}.rowVerifyButton.adjustment{border-color:#f0ad35;background:rgba(240,173,53,.12);color:#ffc65c}.correctionActions{display:flex;align-items:center;gap:14px}.correctionActions button.primary{border-color:#27d995!important;background:rgba(39,217,149,.12)!important;color:#62efb8!important}.correctionActions button:not(.primary){border-color:#ff5368!important;background:rgba(255,83,104,.12)!important;color:#ff7182!important}`}</style>
  {correctionPopup&&<div className="correctionPopup"><div><b>⚠ STAT CORRECTION</b><p>{correctionPopup}</p></div><div className="correctionActions"><button className="primary" onClick={viewCorrection}>VIEW ADJUSTMENT</button><button onClick={dismissCorrection}>DISMISS</button></div></div>}
  {correctionReviewOpen&&<div className="correctionModalBack"><div className="correctionModal"><div className="correctionModalHead"><div><small>OFFICIAL NHL STAT CORRECTION</small><h2>STAT CORRECTION REVIEW</h2></div><button onClick={closeCorrectionReview}>✕</button></div>{correctionReviews.length===0?<p className="correctionEmpty">No unresolved stat adjustments.</p>:correctionReviews.map((r:any)=>{const b=bets.find((x:any)=>x.id===r.betId);return <div className="correctionCard" key={r.betId}><div className="correctionCaseHead"><div><small>OFFICIAL NHL ADJUSTMENT</small><b>{r.deltas?.length?`${r.deltas.length} recorded stat change${r.deltas.length===1?'':'s'}`:'Legacy adjustment · run VERIFY STATS again to capture exact delta'}</b></div><span>{r.gameIds?.length||1} game{(r.gameIds?.length||1)===1?'':'s'} checked</span></div><div className="correctionDelta">{r.deltas?.length?r.deltas.map((d:any,i:number)=><div className="deltaRow" key={`${d.gameId}:${d.player}:${d.stat}:${i}`}><div><small>GAME {d.gameId}</small><b>{d.player}</b></div><strong>{d.stat}</strong><span className="deltaBefore">{d.before}</span><i>→</i><em>{d.after}</em>{d.threshold!=null&&<small className={d.beforeHit!==d.afterHit?'legFlip':''}>{d.player} {d.threshold}+ {d.stat}: {d.beforeHit?'HIT':'MISS'} → {d.afterHit?'HIT':'MISS'}</small>}</div>):<div className="legacyDelta">This adjustment was detected before detailed snapshots were enabled. Re-run VERIFY STATS on its game(s) to capture the exact before → after stat evidence.</div>}</div><div className="correctionBet"><small>AFFECTED WAGER · {b?.book||'Sportsbook'}</small><strong>{b?.legs?.map((l:any)=>`${l.player} ${l.qty}+ ${l.stat}`).join(' + ')}</strong><p>Sportsbook settlement: <b>{r.from}</b> <span>NHL-corrected grade: <b>{r.to}</b></span></p><small>Last checked: {new Date(r.updatedAt||r.createdAt).toLocaleString()}</small></div><div className="correctionDecision"><button onClick={()=>resolveCorrection(r,false)}>KEEP SPORTSBOOK SETTLEMENT</button><button className="apply" onClick={()=>resolveCorrection(r,true)}>APPLY NHL CORRECTION</button></div></div>})}</div></div>}
